# Store the current play index in memory (you can persist it in a file or database if needed)
current_play_index = {"q": 0, "val": 0}

# Simulate game data
game_data = {
    "playGrps": [
       [ {'id': '4017169854', 'period': {'number': 1, 'displayValue': '1st Quarter'}, 'text': 'Domantas Sabonis vs. Draymond Green (Keon Ellis gains possession)', 'homeAway': 'away', 'awayScore': 0, 'homeScore': 0, 'clock': {'displayValue': '12:00'}},
       {'id': '4017169857', 'period': {'number': 1, 'displayValue': '1st Quarter'}, 'text': 'Draymond Green personal foul', 'homeAway': 'home', 'awayScore': 0, 'homeScore': 0, 'clock': {'displayValue': '11:51'}}]
    ]
}

@app.route('/nba/playbyplay/<game_id>')
def play_by_play(game_id):
    return jsonify(game_data)

# This endpoint will simulate new plays being added to the game
@app.route('/nba/update_play', methods=['POST'])
def update_play():
    if current_play_index['q'] >= 4:
        return jsonify({"message": "Game over"})
    length_of_quarter = len(play_list_obj[current_play_index['q']])
    if current_play_index['val'] >= length_of_quarter:
        current_play_index['q'] += 1
        current_play_index['val'] = 0
        game_data["playGrps"].append([])
    # new_play = {"text": play_list[current_play_index['val']]}
    new_play = play_list_obj[current_play_index['q']][current_play_index['val']]
    current_play_index["val"] += 1
    game_data["playGrps"][current_play_index['q']].append(new_play)
    return jsonify({"message": "Play added", "new_play": new_play})

